%[text] # Creating Delta V Surrogate with Initial Mass using PCE
%%
AU = 1.49579151285e8;
mu_star = 1.32712440018e11; % [km3 / s2]
l_star = AU; % [km] one AU
m_star = 3000; % [kg] - max initial ship mass
a_star = mu_star / l_star ^ 2; % [km / s2]
t_star = sqrt(l_star ^ 3 / mu_star);
v_star = sqrt(mu_star/l_star);

year_to_sec = 86400.0 * 365.25;

mu = 1;
mu_dim = mu_star;
m_min = 500 / m_star; % dependent on a lot
t0 = 13.5 * year_to_sec / t_star;
ToF = 0.5 * year_to_sec / t_star;
tf = ToF;
tf_actual = t0 + ToF;
N = 15;

function [dV_max] = max_delta_V(ToF, m0)
    AU = 1.49579151285e8;
    mu_star = 1.32712440018e11; % [km3 / s2]
    l_star = AU; % [km] one AU
    m_star = 3000; % [kg] - max initial ship mass
    a_star = mu_star / l_star ^ 2; % [km / s2]
    t_star = sqrt(l_star ^ 3 / mu_star);
    v_star = sqrt(mu_star/l_star);

    %% Calculate max dV possible for continuous max thrust (ignoring external forces)
    Isp = 4000; % [s]
    g_0 = 9.80665; % [m / s2]
    alpha = 1 / (Isp * g_0); % [s / m]
    u_max = 0.6; % [N]
    
    mf = m0 - alpha * u_max * ToF * t_star / m_star;
    dV_max = Isp * g_0 * log(m0 ./ mf) / 1000 / v_star;
end
%%
% Load data sets
datasets = {};
datasets{1} = load("dataset_1to5000IDs_0p5ToF_1p5yr_0p90m.mat").dataset;
datasets{2} = load("dataset_1to5000IDs_0p5ToF_3p6yr_0p80m.mat").dataset;
datasets{3} = load("dataset_1to5000IDs_0p5ToF_5p7yr_0p70m.mat").dataset;
datasets{4} = load("dataset_1to5000IDs_0p5ToF_7p8yr_0p60m.mat").dataset;
datasets{5} = load("dataset_1to5000IDs_0p5ToF_9p8yr_0p50m.mat").dataset;
datasets{6} = load("dataset_1to5000IDs_0p5ToF_11p9yr_0p40m.mat").dataset;
datasets{7} = load("dataset_1to4000IDs_0p5ToF_13p5yr_0p35m.mat").dataset;
datasets{8} = load("dataset_1to3000IDs_0p5ToF_14p0yr_0p30m.mat").dataset;
datasets{9} = load("dataset_1to1000IDs_0p5ToF_13p5yr_0p28m.mat").dataset;
datasets{10} = load("dataset_1to1000IDs_0p5ToF_13p5yr_0p25m.mat").dataset;

m0_array = [0.9, 0.8, 0.7, 0.6, 0.5, 0.4, 0.35, 0.3, 0.28, 0.25]; % make part of dataset objects...
%%
dataset_combined = [];
dataset_combined.dV_max = [];
dataset_combined.dV_lambert = [];
dataset_combined.dV_lowthrust = [];
dataset_combined.dV_ratio = [];
dataset_combined.v1_ast = [];
dataset_combined.v2_ast = [];
dataset_combined.v1_lambert = [];
dataset_combined.v2_lambert = [];
dataset_combined.x_1 = [];
dataset_combined.x_2 = [];
dataset_combined.m0 = [];
dataset_combined.ToF = [];

for i = 1 : numel(datasets)
    dataset_combined.dV_max = [dataset_combined.dV_max, max_delta_V(datasets{i}.ToF, m0_array(i)) * ones([1, numel(datasets{i}.dV_lambert)])];
    dataset_combined.dV_lambert = [dataset_combined.dV_lambert, datasets{i}.dV_lambert];
    dataset_combined.dV_lowthrust = [dataset_combined.dV_lowthrust, datasets{i}.dV_lowthrust];
    dataset_combined.dV_ratio = [dataset_combined.dV_ratio, datasets{i}.dV_ratio];
    dataset_combined.v1_ast = [dataset_combined.v1_ast, datasets{i}.v1_ast];
    dataset_combined.v2_ast = [dataset_combined.v2_ast, datasets{i}.v2_ast];
    dataset_combined.v1_lambert = [dataset_combined.v1_lambert, datasets{i}.v1_lambert];
    dataset_combined.v2_lambert = [dataset_combined.v2_lambert, datasets{i}.v2_lambert];
    dataset_combined.x_1 = [dataset_combined.x_1, datasets{i}.x_1];
    dataset_combined.x_2 = [dataset_combined.x_2, datasets{i}.x_2];
    dataset_combined.m0 = [dataset_combined.m0, m0_array(i) * ones([1, numel(datasets{i}.dV_lambert)])];
    dataset_combined.ToF = [dataset_combined.ToF, datasets{i}.ToF * ones([1, numel(datasets{i}.dV_lambert)])];
end
%%
figure %[output:8b874523]
scatter(dataset_combined.dV_lambert ./ dataset_combined.dV_max, dataset_combined.dV_ratio) %[output:8b874523]
%%

unique(dataset_combined.dV_max) %[output:7a99c074]
%%
fitResult_x = {};
%%
h = histfit(dataset_combined.dV_lambert ./ dataset_combined.dV_max, 100, "normal"); %[output:964a0d7b]
fitResult_dV_lambert = fitdist(dataset_combined.dV_lambert' ./ dataset_combined.dV_max', "Normal") % Fit the model to the data %[output:7b508bcc]
%%
histfit(dataset_combined.v1_ast(3, :) - dataset_combined.v1_lambert(3, :), 100, "normal") %[output:8a7f2893]
fitResult_vdiff{1}{1} = fitdist(dataset_combined.v1_ast(1, :)' - dataset_combined.v1_lambert(1, :)', "Normal");
fitResult_vdiff{1}{2} = fitdist(dataset_combined.v2_ast(1, :)' - dataset_combined.v2_lambert(1, :)', "Normal");
fitResult_vdiff{2}{1} = fitdist(dataset_combined.v1_ast(2, :)' - dataset_combined.v1_lambert(2, :)', "Normal");
fitResult_vdiff{2}{2} = fitdist(dataset_combined.v2_ast(2, :)' - dataset_combined.v2_lambert(2, :)', "Normal");
fitResult_vdiff{3}{1} = fitdist(dataset_combined.v1_ast(3, :)' - dataset_combined.v1_lambert(3, :)', "Normal");
fitResult_vdiff{3}{2} = fitdist(dataset_combined.v2_ast(3, :)' - dataset_combined.v2_lambert(3, :)', "Normal");

histfit(dataset_combined.v2_ast(3, :) - dataset_combined.v2_lambert(3, :), 100, "normal") %[output:47bd5a15]
%%
%[text] ## Surrogate Model
%[text] 12 Inputs: Lambert dV, x\_1\_me(1:5), x\_2\_me(1:5), angle difference of true longitude         - (give both dV for lambert or actual vecter info? asteroid velocity vectors?)
%[text] 1 Output: Low thrust dV / Lambert dV        - (or just low thrust dV?)
uqlab %[output:7f7ac059]
%%
X_inputs = [dataset_combined.v1_ast(1, :) - dataset_combined.v1_lambert(1, :);
            dataset_combined.v2_ast(1, :) - dataset_combined.v2_lambert(1, :);
            dataset_combined.v1_ast(2, :) - dataset_combined.v1_lambert(2, :);
            dataset_combined.v2_ast(2, :) - dataset_combined.v2_lambert(2, :);
            dataset_combined.v1_ast(3, :) - dataset_combined.v1_lambert(3, :);
            dataset_combined.v2_ast(3, :) - dataset_combined.v2_lambert(3, :);
            dataset_combined.dV_lambert ./ dataset_combined.dV_max;
            dataset_combined.m0];

index = 1;

InputOpts = [];

% Asteroid and lambert velocity vector differences
for i = 1 : 3
    for j = 1 : 2
        InputOpts.Marginals(index).Name = sprintf('vdiff_%g_%g', j, i);
        InputOpts.Marginals(index).Type = fitResult_vdiff{i}{j}.DistributionName; 
        InputOpts.Marginals(index).Moments = fitResult_vdiff{i}{j}.ParameterValues; % matlab always match UQ lab?
        index = index + 1;
    end
end

% Lambert delta V
InputOpts.Marginals(index).Name = 'dVLambert';
InputOpts.Marginals(index).Type = fitResult_dV_lambert.DistributionName;
InputOpts.Marginals(index).Moments = fitResult_dV_lambert.ParameterValues;
%InputOpts.Marginals(index).Bounds = [0, 1];
index = index + 1;

% Initial mass
InputOpts.Marginals(index).Name = 'm0';
InputOpts.Marginals(index).Type = 'Uniform';
InputOpts.Marginals(index).Moments = [m_min, 1];
%InputOpts.Marginals(index).Bounds = [0, 1];
index = index + 1;

for i = 1 : numel(InputOpts.Marginals)
    if strcmp(InputOpts.Marginals(i).Type, 'Normal')
        InputOpts.Marginals(i).Type = 'Gaussian';
    end
end

myInput = uq_createInput(InputOpts);

uq_print(myInput); %[output:5d75ca8e]
%%
% Fit
MetaOpts = [];
MetaOpts.Type = 'Metamodel';
MetaOpts.MetaType = 'PCE';

train_portion = 0.7;
indices = [ones([1, floor(train_portion * numel(dataset_combined.dV_lambert))]), zeros([1, ceil((1 - train_portion) * numel(dataset_combined.dV_lambert))])];
train_i = logical(indices(randperm(numel(indices))));
test_i = ~train_i;

MetaOpts.ExpDesign.X = X_inputs(:, train_i)';
MetaOpts.ExpDesign.Y = dataset_combined.dV_lowthrust(train_i)' ./ dataset_combined.dV_max(train_i)';

MetaOpts.Degree = 1:3;
MetaOpts.Method = 'LARS';

MetaOpts.ValidationSet.X = X_inputs(:, test_i)';
MetaOpts.ValidationSet.Y = dataset_combined.dV_lowthrust(test_i)' ./ dataset_combined.dV_max(test_i)';

%MetaOpts.PolyTypes = {'legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre','legendre'};
%MetaOpts.PolyTypes = {'arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary','arbitrary'};

myPCE = uq_createModel(MetaOpts); %[output:4ff43965]
uq_print(myPCE) %[output:3d5c5247]
uq_display(myPCE) %[output:6fd35610]
%%
%[text] ## Validation
Yval = dataset_combined.dV_lowthrust(test_i)' ./ dataset_combined.dV_max(test_i)';

Ylamb = dataset_combined.dV_lambert(test_i)' ./ dataset_combined.dV_max(test_i)';

YPCE = uq_evalModel(myPCE, X_inputs(:, test_i)');

uq_figure %[output:53e66e49]

cmap = uq_colorOrder(3);
uq_histogram(Ylamb, 'FaceColor', cmap(1,:)) %[output:53e66e49]
hold on %[output:53e66e49]
uq_histogram(Yval, 'FaceColor', cmap(2,:)) %[output:53e66e49]
hold on %[output:53e66e49]
uq_histogram(YPCE, 'FaceColor', cmap(3,:)) %[output:53e66e49]
hold off %[output:53e66e49]

xlabel('$\mathrm{Y}$') %[output:53e66e49]
ylabel('Counts') %[output:53e66e49]
uq_legend(... %[output:group:9dd68401] %[output:53e66e49]
    {'Lambert', 'True model response', 'PCE prediction'},... %[output:53e66e49]
    'Location', 'northwest') %[output:group:9dd68401] %[output:53e66e49]

uq_figure
%%
uq_plot(Ylamb, Yval, 'x') %[output:059b34a3]
hold on %[output:059b34a3]
uq_plot(YPCE, Yval, '+') %[output:059b34a3]
hold on %[output:059b34a3]
uq_plot([min(Yval) max(Yval)], [min(Yval) max(Yval)], 'k') %[output:059b34a3]
hold off %[output:059b34a3]

axis equal %[output:059b34a3]
axis([min(Yval) max(Yval) min(Yval) max(Yval)]) %[output:059b34a3]

ylabel('$\mathrm{Y_{true}}$') %[output:059b34a3]
xlabel('$\mathrm{Y_{Lamb,PCE}}$') %[output:059b34a3]
legend("Lamb", "PCE") %[output:059b34a3]
%%
fprintf('PCE metamodel validation error: %5.4e\n', myPCE.Error.Val) %[output:180496c8]
fprintf('PCE metamodel LOO error:        %5.4e\n', myPCE.Error.LOO) %[output:963b4269]
%%
%% Sobol Indices Sensitivity Analysis
% Set up analysis
SobolOpts.Type = 'Sensitivity';
SobolOpts.Method = 'Sobol';
SobolOpts.Sobol.Order = 1;

% Run analysis
mySobolAnalysisPCE = uq_createAnalysis(SobolOpts); %[output:18355f0d]

%% Display Sensitivity Analysis Results
uq_display(mySobolAnalysisPCE) %[output:94ed8997] %[output:78b594f7]
%%\
uq_figure() %[output:4c4586e2]
uq_bar(1:numel(mySobolAnalysisPCE.Results.Total), mySobolAnalysisPCE.Results.Total, 0.25) %[output:4c4586e2]
% Set axes limits
ylim([0 1]) %[output:4c4586e2]
