xlabel('Variable name') %[output:4c4586e2]
ylabel('Total Sobol'' indices') %[output:4c4586e2]
set(gca, 'XTick', 1:length(InputOpts.Marginals),... %[output:4c4586e2]
    'XTickLabel', mySobolAnalysisPCE.Results.VariableNames) %[output:4c4586e2]
% Set Title
title(sprintf('PCE-based Sobol Indice Sensitivity Analysis (%d simulations)', myPCE.ExpDesign.NSamples)) %[output:4c4586e2]
