uq_legend({... %[output:group:29604ef9] %[output:7082b9b1] %[output:4c4586e2]
    "Final $\sigma_{r_x}$", "Final $\sigma_{r_y}$"},... %[output:7082b9b1] %[output:4c4586e2]
    'Location', 'northeast', "Interpreter", "latex") %[output:group:29604ef9] %[output:7082b9b1] %[output:4c4586e2]
%%
%[text] ## dV ratio
% Fit
MetaOpts.Type = 'Metamodel';
MetaOpts.MetaType = 'PCE';

train_portion = 0.7;
indices = [ones([1, floor(train_portion * numel(dataset_combined.dV_lambert))]), zeros([1, ceil((1 - train_portion) * numel(dataset_combined.dV_lambert))])];
train_i = logical(indices(randperm(numel(indices))));
test_i = ~train_i;

MetaOpts.ExpDesign.X = X_inputs(:, train_i)';
%MetaOpts.ExpDesign.Y = dataset_combined.dV_lowthrust(train_i)' / dV_max;
MetaOpts.ExpDesign.Y = dataset_combined.dV_ratio(train_i)';

MetaOpts.Degree = 1:3;

MetaOpts.ValidationSet.X = X_inputs(:, test_i)';
%MetaOpts.ValidationSet.Y = dataset_combined.dV_lowthrust(test_i)' / dV_max;
MetaOpts.ValidationSet.Y = dataset_combined.dV_ratio(test_i)';

myPCE_ratio = uq_createModel(MetaOpts); %[output:48531db7]
uq_print(myPCE_ratio) %[output:7f799102]
uq_display(myPCE_ratio) %[output:2a9dc184]
%%
%[text] ## Validation
Yval = dataset_combined.dV_lowthrust(test_i)' ./ dataset_combined.dV_max(test_i)';
%Yval = dataset_combined.dV_ratio(test_i)';

Ylamb = dataset_combined.dV_lambert(test_i)' ./ dataset_combined.dV_max(test_i)';
%Ylamb = ones(size(Yval));

YPCE = uq_evalModel(myPCE_ratio, X_inputs(:, test_i)') .* dataset_combined.dV_lambert(test_i)' ./ dataset_combined.dV_max(test_i)';

uq_figure %[output:0b833922]

cmap = uq_colorOrder(3);
uq_histogram(Ylamb, 'FaceColor', cmap(1,:)) %[output:0b833922]
hold on %[output:0b833922]
uq_histogram(Yval, 'FaceColor', cmap(2,:)) %[output:0b833922]
hold on %[output:0b833922]
uq_histogram(YPCE, 'FaceColor', cmap(3,:)) %[output:0b833922]
hold off %[output:0b833922]

xlabel('$\mathrm{Y}$') %[output:0b833922]
ylabel('Counts') %[output:0b833922]
uq_legend(... %[output:group:6efdf17c] %[output:0b833922]
    {'Lambert', 'True model response', 'PCE prediction'},... %[output:0b833922]
    'Location', 'northwest') %[output:group:6efdf17c] %[output:0b833922]

uq_figure
%%
uq_plot(Ylamb, Yval, 'x') %[output:64b42241]
hold on %[output:64b42241]
