xlabel('$\mathrm{Y_{Lamb,PCE}}$') %[output:64b42241]
legend("Lamb", "PCE") %[output:64b42241]
%%
fprintf('PCE metamodel validation error: %5.4e\n', myPCE_ratio.Error.Val) %[output:2f646684]
fprintf('PCE metamodel LOO error:        %5.4e\n', myPCE_ratio.Error.LOO) %[output:6ddf7a94]
